	if !strings.Contains(req.Email, "@") {
		return validationError{"email", "must contain @"}
	}
	if strings.TrimSpace(req.Name) == "" {
		return validationError{"name", "is required"}
	}
	if len(req.Name) > 80 {
		return validationError{"name", "must be at most 80 characters"}
	}
